  "test": "import pytest
from mcp.server.lowlevel.server import NotificationOptions

def test_notification_options_to_dict():
    opts = NotificationOptions(prompts_changed=True, resources_changed=False, tools_changed=True)
    assert opts.to_dict() == {
        "prompts_changed": True,
        "resources_changed": False,
        "tools_changed": True,
    }

def test_notification_options_default_to_dict():
    opts = NotificationOptions()
    assert opts.to_dict() == {
        "prompts_changed": False,
        "resources_changed": False,
        "tools_changed": False,
    }"
}
